const $=s=>document.querySelector(s),messages=$('#messages'),input=$('#promptInput');let selectedPlugin=null;const cyberTerms=/\b(cybersecurity|cyber security|security|hacking|hacker|ethical hacking|pentest|penetration test|vulnerability|vulnerabilities|exploit|exploitation|malware|ransomware|phishing|social engineering|ctf|soc|siem|firewall|encryption|cryptography|forensics|incident response|zero[- ]day|xss|sql injection|sqli|csrf|ddos|botnet|reverse shell|payload)\b/i;const cyberAlertTerms=/\b(ransomware|malware|phishing|credential theft|steal credentials|ddos|botnet|zero[- ]day|exploit|exploitation|payload|reverse shell|shellcode|attack|breach|incident)\b/i;function applyContextTheme(text){const t=String(text||'');const cyber=cyberTerms.test(t);document.body.classList.toggle('cyber-ui',cyber);document.body.classList.toggle('cyber-alert',cyber&&cyberAlertTerms.test(t));localStorage.setItem('haxbro_context_theme',cyber?'cyber':'normal')}function updateCustomerProfile(name){const card=$('#customerProfile'),avatar=$('#customerProfileAvatar'),label=$('#customerProfileName'),role=$('#customerProfileRole');const n=String(name||localStorage.getItem('haxbro_username')||'').trim();if(!card||!avatar||!label)return;if(overdrive&&overdrive===true){avatar.textContent='A';label.textContent='A';if(role)role.textContent='ADMIN MODE · HAxBRO OWNER';card.hidden=false;avatar.style.background='linear-gradient(135deg,#7f0715,#ff1f3d)';return}if(!n){card.hidden=true;return}const first=(n.match(/[A-Za-z0-9]/)||['?'])[0].toUpperCase();let sum=0;for(let i=0;i<n.length;i++)sum+=n.charCodeAt(i)*(i+1);const colors=['linear-gradient(135deg,#315cff,#159bd8)','linear-gradient(135deg,#e23b5d,#ff7a59)','linear-gradient(135deg,#7c3aed,#21d4fd)','linear-gradient(135deg,#00a86b,#315cff)','linear-gradient(135deg,#f59e0b,#ef4444)','linear-gradient(135deg,#0ea5e9,#8b5cf6)'];avatar.textContent=first;avatar.style.background=colors[sum%colors.length];label.textContent=n;card.hidden=false}let mode=localSto