async function runAdminKaiBrowser(request){const raw=String(request||'').trim();const m=raw.match(/^(?:Kai\s*5\s*,?\s*)?(?:go to|open|navigate to|visit|browse)\s+(https?:\/\/\S+?)(?:\s+(?:and\s+)?click\s+(.+))?$/i);if(!m)return false;if(!overdrive&&/^Kai\s*5\b/i.test(raw))return false;const url=m[1].replace(/[),.;]+$/,'');const clickText=(m[2]||'').trim().replace(/^['\"]|['\"]$/g,'');addMessage(request,'user');const thinking=addMessage('KAI 5 · BROWSER — opening managed Chromium…','bot',false);try{const r=await fetch('/api/kai/browser',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url,clickText})});const d=await r.json();thinking.remove();if(!r.ok)throw new Error(d.error||'Browser action failed');const result=[`KAI 5 · BROWSER READY`,`URL: ${d.url||url}`,`TITLE: ${d.title||'Unknown'}`,clickText?`ACTION: clicked “${clickText}”`:'ACTION: navigation complete',d.text?`\nPAGE SNAPSHOT:\n${String(d.text).slice(0,3500)}`:''].filter(Boolean).join('\n');addMessage(result);return true}catch(e){thinking.remove();addMessage('KAI 5 · BROWSER ERROR: '+(e?.message||e));return true}}
