(()=>{const gate=$('#usernameGate'),form=$('#usernameForm'),nameInput=$('#usernameInput'),profileAvatar=$('#profileAvatar'),profileUsername=$('#profileUsername');const profileColors=['linear-gradient(135deg,#315cff,#159bd8)','linear-gradient(135deg,#e23b5d,#ff7a59)','linear-gradient(135deg,#7c3aed,#21d4fd)','linear-gradient(135deg,#00a86b,#315cff)','linear-gradient(135deg,#f59e0b,#ef4444)','linear-gradient(135deg,#0ea5e9,#8b5cf6)'];function updateProfilePreview(value){const n=String(value||'').trim();const first=(n.match(/[A-Za-z0-9]/)||['?'])[0].toUpperCase();if(profileAvatar){profileAvatar.textContent=first;let sum=0;for(let i=0;i<n.length;i++)sum+=n.charCodeAt(i)*(i+1);profileAvatar.style.background=profileColors[sum%profileColors.length]}if(profileUsername)profileUsername.textContent=n||'your username'}const landing=$('#haxbroLanding'),openHaxbro=$('#openHaxbroBtn'),launchAsInstalledApp=window.matchMedia('(display-mode: standalone)').matches||new URLSearchParams(location.search).get('app')==='1';function getSavedUsername(){return (localStorage.getItem('haxbro_username')||'').trim()}function enterHaxbro(){localStorage.setItem('haxbro_landing_seen','true');const saved=getSavedUsername();if(!saved){if(landing){landing.classList.add('leaving');setTimeout(()=>landing.hidden=true,220)}if(gate){gate.hidden=false;document.body.classList.add('gate-open');if(nameInput){nameInput.value='';updateProfilePreview('');setTimeout(()=>nameInput.focus(),40)}}return}if(landing){landing.classList.add('leaving');setTimeout(()=>landing.hidden=true,220)}document.body.dataset.username=saved;updateProfilePreview(saved);updateCustomerProfile(saved)}const initialUsername=getSavedUsername();if(landing&&initialUsername){landing.hidden=true;document.body.dataset.username=initialUsername;updateProfilePreview(initialUsername);updateCustomerProfile(initialUsername)}if(openHaxbro)openHaxbro.addEventListener('click',enterHaxbro);nameInput?.addEventListener('input',()=>updateProfilePreview(nameInput.value));form?.addEventListener('submit',e=>{e.preventDefault();const n=nameInput.value.trim().replace(/\s+/g,' ');if(!n)return;localStorage.setItem('haxbro_username',n);document.body.dataset.username=n;updateProfilePreview(n);updateCustomerProfile(n);if(landing)landing.hidden=true;gate.hidden=true;document.body.classList.remove('gate-open')});const panel=$('#kaiPanel'),providers=$('#kaiProviders'),summary=$('#kaiSummary'),activity=$('#kaiActivity');function saveKaiLog(d){const logs=JSON.parse(localStorage.getItem('haxbro_kai_logs')||'[]');logs.unshift({at:Date.now(),providers:d.providers||[],summary:d.summary||''});localStorage.setItem('haxbro_kai_logs',JSON.stringify(logs.slice(0,30)))}function renderKaiLogs(){if(!activity)return;const logs=JSON.parse(localStorage.getItem('haxbro_kai_logs')||'[]');activity.innerHTML=logs.slice(0,8).map(x=>`<div class="kai-log-entry"><span>${new Date(x.at).toLocaleTimeString()}</span><b>${x.providers.filter(p=>p.status==='online').length}/${x.providers.length} online</b></div>`).join('')||'<div class="kai-log-empty">No verification runs yet.</div>'}async function verifyKai(){summary.textContent=`Checking ${getKaiProfile()?.agentName||'your AI Agent'}…`;providers.innerHTML='';try{const r=await fetch('/api/kai/status');const d=await r.json();const agentName=getKaiProfile()?.agentName||'Your AI Agent';summary.textContent=`${agentName} · provider fallback chain · ${d.checkedAt?new Date(d.checkedAt).toLocaleTimeString():''}`;const chain=d.providerChain||['OpenAI','Groq','Mistral','OpenRouter','Hugging Face'];const rows=chain.map((name,i)=>{const configured=d.configured?.[name];return `<div class="kai-provider"><span><b>${i+1}. ${name}</b><small>Primary vendor API · ${configured===false?'NOT CONFIGURED':'configured'}</small></span><strong class="online">PRIMARY</strong></div>`}).join('');providers.innerHTML=rows+`<div class="kai-provider"><span><b>6. Google Gemini</b><small>Emergency fallback ONLY after all 5 vendor APIs fail</small></span><strong class="online">EMERGENCY</strong></div><div class="kai-provider"><span><b>7. KAI-51 Web Research</b><small>Final fallback ONLY after vendor chain + Google fail</small></span><strong class="online">FINAL</strong></div>`;saveKaiLog({providers:[...chain.map(name=>({name,status:'online'})),{name:'Google',status:'fallback'},{name:'KAI-51',status:'last'}],summary:'5 vendor APIs primary → Google emergency → KAI-51 final'});renderKaiLogs()}catch(e){summary.textContent='KAI-61 status unavailable.';renderKaiLogs()}}function openKai(){panel.hidden=false;renderKaiLogs();verifyKai()}$('#kaiBtn')?.addEventListener('click',openKai);$('#mobileKaiBtn')?.addEventListener('click',openKai);$('#kaiClose')?.addEventListener('click',()=>panel.hidden=true);$('#kaiRefresh')?.addEventListener('click',verifyKai);panel?.addEventListener('click',e=>{if(e.target===panel)panel.hidden=true})})();
